INSERT INTO `wp_gplcellar_items_tbl` VALUES (2464,'MEC Waiting List','plugin',0,'1.4.5','mec-waiting-list/mec-waiting-list.php','https://files.gplcellar.com/2026/01/modern-events-calendar-10.jpg','This addon enables you to create a waiting form after selling out the tickets, so people can reserve one in case one of the attendees cancel their reservation. The people in the waiting list get transferred to the main list based on their reservation priority.','https://www.gplcellar.com/product/mec-waiting-list/','','2025-11-27',0,0,17658,'[{\"version\":\"1.4.5\",\"filename\":\"mec-waiting-list.1.4.5.zip\"},{\"version\":\"1.3.1\",\"filename\":\"mec-waiting-list.1.3.1.zip\"}]');
