INSERT INTO `wp_posts` VALUES (24,1,'2025-12-01 14:59:59','2025-12-01 12:59:59','<!-- wp:paragraph -->\n<p>Επικοινωνία</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Για οποιαδήποτε απορία, εισήγηση ή θέμα που αφορά τον Σύνδεσμο Γονέων, μπορείτε να επικοινωνήσετε μαζί μας χρησιμοποιώντας τα παρακάτω στοιχεία.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Στοιχεία Επικοινωνίας:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Email: info@syndesmosgoneon.com</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {\"fontSize\":\"normal\"} -->\n<li class=\"has-normal-font-size\">Τηλέφωνο Σχολείου: <a href=\"tel:25123456\"><strong>25 123456</strong></a></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Ωράριο επικοινωνίας:<br>Δευτέρα – Παρασκευή: 08:00 – 13:00<br>(εκτός σχολικών αργιών)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Φόρμα Επικοινωνίας:<br>Μπορείτε να στείλετε το μήνυμά σας μέσω της παρούσας σελίδας και θα σας απαντήσουμε το συντομότερο δυνατό.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Στόχος μας είναι η άμεση και αποτελεσματική εξυπηρέτηση όλων των γονέων και η συνεχής ενίσχυση της συνεργασίας μεταξύ σχολείου και οικογένειας.</p>\n<!-- /wp:paragraph -->','Επικοινωνία','','publish','closed','closed','','%ce%b5%cf%80%ce%b9%ce%ba%ce%bf%ce%b9%ce%bd%cf%89%ce%bd%ce%af%ce%b1','','','2025-12-01 18:56:32','2025-12-01 16:56:32','',0,'http://localhost:10018/?page_id=24',0,'page','',0);
