INSERT INTO `wp_posts` VALUES (82,1,'2025-12-01 18:44:56','2025-12-01 16:44:56','<!-- wp:paragraph -->\n<p>Δοκιμαστική ανακοίνωση.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Αγαπητοί γονείς,</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Σας ενημερώνουμε ότι ο Σύνδεσμος Γονέων ξεκινά τη φετινή σχολική χρονιά με μια σειρά από δράσεις και πρωτοβουλίες που αποσκοπούν στη στήριξη των μαθητών και της σχολικής κοινότητας.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Σύντομα θα ανακοινωθούν:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>νέες εκπαιδευτικές δραστηριότητες,</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>προγραμματισμένες εκδηλώσεις,</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>τρόποι ενίσχυσης του σχολείου και συμμετοχής των γονέων.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Παρακαλούμε να παρακολουθείτε τις ανακοινώσεις μας για συνεχή ενημέρωση.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Με εκτίμηση,<br>Ο Σύνδεσμος Γονέων</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":80,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:10018/wp-content/uploads/2025/12/image.png\" alt=\"\" class=\"wp-image-80\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','Ανακοίνωση 1','','inherit','closed','closed','','44-revision-v1','','','2025-12-01 18:44:56','2025-12-01 16:44:56','',44,'http://localhost:10018/?p=82',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (83,1,'2025-12-01 18:46:51','2025-12-01 16:46:51','','image','','inherit','open','closed','','image-2','','','2025-12-01 18:46:51','2025-12-01 16:46:51','',46,'http://localhost:10018/wp-content/uploads/2025/12/image-1.png',0,'attachment','image/png',0);
INSERT INTO `wp_posts` VALUES (84,1,'2025-12-01 18:47:08','2025-12-01 16:47:08','<!-- wp:paragraph -->\n<p>Δοκιμαστική ανακοίνωση 2.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Αγαπητοί γονείς,</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Θα θέλαμε να σας ενημερώσουμε ότι στις επόμενες εβδομάδες θα πραγματοποιηθεί σειρά εκπαιδευτικών και ψυχαγωγικών δραστηριοτήτων για τους μαθητές του σχολείου μας.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Στόχος των δράσεων αυτών είναι:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>η ενίσχυση της δημιουργικότητας,</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>η καλλιέργεια συνεργασίας μεταξύ των μαθητών,</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>η ενεργή συμμετοχή της σχολικής κοινότητας.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Το αναλυτικό πρόγραμμα θα κοινοποιηθεί σύντομα μέσω της ιστοσελίδας και της σελίδας μας στα κοινωνικά δίκτυα.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Σας ευχαριστούμε για τη συνεχή στήριξη και συνεργασία.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Με εκτίμηση,<br>Ο Σύνδεσμος Γονέων</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":83,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost:10018/wp-content/uploads/2025/12/image-1-1024x465.png\" alt=\"\" class=\"wp-image-83\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','Ανακοίνωση 2','','inherit','closed','closed','','46-revision-v1','','','2025-12-01 18:47:08','2025-12-01 16:47:08','',46,'http://localhost:10018/?p=84',0,'revision','',0);
