INSERT INTO `wp_posts` VALUES (87,1,'2025-12-01 18:49:18','2025-12-01 16:49:18','<!-- wp:paragraph -->\n<p>Δοκιμαστική εκδήλωση.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Αγαπητοί γονείς και κηδεμόνες,</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Σας ενημερώνουμε ότι το σχολείο μας θα πραγματοποιήσει μια ειδική εκδήλωση μέσα στις επόμενες εβδομάδες με στόχο την ενίσχυση της συμμετοχής των μαθητών σε δημιουργικές και ομαδικές δραστηριότητες.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Η εκδήλωση θα περιλαμβάνει:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>μικρές παρουσιάσεις από τους μαθητές,</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>θεατρικά και μουσικά δρώμενα,</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>δημιουργικά εργαστήρια,</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>ψυχαγωγικές δραστηριότητες για όλες τις ηλικίες.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Το αναλυτικό πρόγραμμα και οι ώρες συμμετοχής θα ανακοινωθούν σύντομα.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Σας προσκαλούμε όλους να παρευρεθείτε και να στηρίξετε τις προσπάθειες των μαθητών μας.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Με εκτίμηση,<br>Ο Σύνδεσμος Γονέων</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":85,\"width\":\"381px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://localhost:10018/wp-content/uploads/2025/12/image-2.png\" alt=\"\" class=\"wp-image-85\" style=\"width:381px;height:auto\"/></figure>\n<!-- /wp:image -->','Εκδήλωση 1','','inherit','closed','closed','','48-revision-v1','','','2025-12-01 18:49:18','2025-12-01 16:49:18','',48,'http://localhost:10018/?p=87',0,'revision','',0);
