INSERT INTO `wp_posts` VALUES (101,1,'2025-12-01 19:04:05','2025-12-01 17:04:05','<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Στη σελίδα αυτή μπορείτε να δείτε στιγμές από τη σχολική ζωή των μαθητών, τις εκδηλώσεις που διοργανώνει ο Σύνδεσμος Γονέων, καθώς και διάφορες δραστηριότητες της σχολικής κοινότητας.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Οι φωτογραφίες ανανεώνονται σε τακτική βάση, ώστε να υπάρχει πάντα διαθέσιμο νέο υλικό που αποτυπώνει τη συμμετοχή και τη δημιουργικότητα των παιδιών.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:gallery {\"linkTo\":\"none\"} -->\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped\"><!-- wp:image {\"id\":98,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"is-style-default\"} -->\n<figure class=\"wp-block-image size-large is-style-default\"><img src=\"http://localhost:10018/wp-content/uploads/2025/12/image-6-1024x683.png\" alt=\"\" class=\"wp-image-98\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":83,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost:10018/wp-content/uploads/2025/12/image-1-1024x465.png\" alt=\"\" class=\"wp-image-83\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":80,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost:10018/wp-content/uploads/2025/12/image.png\" alt=\"\" class=\"wp-image-80\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":52,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost:10018/wp-content/uploads/2025/12/fe01e8b7-4c47-40c8-8876-5469f73f9686-1024x683.png\" alt=\"\" class=\"wp-image-52\"/></figure>\n<!-- /wp:image --></figure>\n<!-- /wp:gallery -->','Φωτογραφίες','','inherit','closed','closed','','22-revision-v1','','','2025-12-01 19:04:05','2025-12-01 17:04:05','',22,'http://localhost:10018/?p=101',0,'revision','',0);
